app.put("/api/shops/settings", verifikasiAksesWarung, cekMasaAktifSub, async (c2) => {
  try {
    const pool = getDbPool(c2);
    const s3 = getS3Client(c2);
    const body = await c2.req.parseBody();
    const shopSlug = body.shop || c2.req.query("shop") || c2.req.header("x-shop-slug");
    const shopId = await getShopIdBySlug(pool, shopSlug);
    if (!shopId) {
      return c2.json({ success: false, message: "Warung tidak ditemukan." }, 404);
    }
    const show_cash_payment = body.show_cash_payment === "1" || body.show_cash_payment === 1 ? 1 : 0;
    const has_tax = body.has_tax === "1" || body.has_tax === 1 ? 1 : 0;
    const is_stock_calculated = body.is_stock_calculated === "1" || body.is_stock_calculated === 1 ? 1 : 0;
    const tax_percentage = parseFloat(body.tax_percentage) || 0;
    const discount_percentage = parseFloat(body.discount_percentage) || 0;
    const bank_rekening_info = body.bank_rekening_info || null;
    let qrisUrlQuery = "";
    let params = [show_cash_payment, has_tax, is_stock_calculated, tax_percentage, discount_percentage, bank_rekening_info];
    const file = body.qris_image;
    if (file && typeof file === "object" && file.name) {
      const fileExtension = file.name.split(".").pop();
      const uniqueFilename = `qris-${Date.now()}-${crypto_default.randomBytes(4).toString("hex")}.${fileExtension}`;
      const arrayBuffer = await file.arrayBuffer();
      await s3.send(new PutObjectCommand({
        Bucket: c2.env.R2_BUCKET_STR,
        Key: uniqueFilename,
        Body: Buffer.from(arrayBuffer),
        ContentType: file.type || "image/jpeg"
      }));
      const urlFoto = `${c2.env.R2_PUBLIC_URL}/${uniqueFilename}`;
      qrisUrlQuery = ", qris_image_url = ?";
      params.push(urlFoto);
    }
    params.push(shopId);
    const queryText = `
            UPDATE shops 
            SET show_cash_payment = ?, has_tax = ?, is_stock_calculated = ?, tax_percentage = ?, discount_percentage = ?, bank_rekening_info = ? ${qrisUrlQuery} 
            WHERE id = ?
        `;
    await pool.prepare(queryText).bind(...params).run();
    return c2.json({ success: true, message: "Pengaturan toko berhasil diperbarui!" });
  } catch (error3) {
    console.error("Error update setting toko:", error3);
    return c2.json({ success: false, message: "Gagal menyimpan pengaturan toko: " + error3.message }, 500);
  }
});
